import importlib.util
import pathlib
import unittest

ROOT = pathlib.Path(__file__).parents[1]
SPEC = importlib.util.spec_from_file_location('greeting', ROOT / 'src/greeting.py')
module = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(module)

class GreetingTests(unittest.TestCase):
    def test_default(self):
        self.assertEqual(module.greet('Ada'), 'Hello, Ada')
    def test_excited(self):
        self.assertEqual(module.greet('Ada', excited=True), 'Hello, Ada!')
    def test_explicit_false(self):
        self.assertEqual(module.greet('', excited=False), 'Hello, ')
    def test_empty_excited(self):
        self.assertEqual(module.greet('', excited=True), 'Hello, !')
